package banghak.home.halley.adapter.outbound.persistence;
import banghak.home.halley.domain.budget.BudgetItemCatalog; import org.jooq.DSLContext; import org.jooq.Record; import org.springframework.stereotype.Repository; import java.util.List; import java.util.Optional;
import static banghak.home.halley.adapter.outbound.persistence.support.JooqMapping.toInstant;
import static banghak.home.halley.adapter.outbound.persistence.jdbc.HouseholdBudgetItemCatalogTable.*;
@Repository public class HouseholdBudgetItemCatalogRepository { private final DSLContext dsl; public HouseholdBudgetItemCatalogRepository(DSLContext dsl){this.dsl=dsl;} public List<BudgetItemCatalog> findAll(){return dsl.selectFrom(TABLE).orderBy(ID).fetch().map(this::map);} public Optional<BudgetItemCatalog> findBySeedKey(String key){return dsl.selectFrom(TABLE).where(SEED_KEY.eq(key)).fetchOptional().map(this::map);} private BudgetItemCatalog map(Record r){return new BudgetItemCatalog(r.get(ID),r.get(SEED_KEY),r.get(CATEGORY),r.get(ITEM_NAME),r.get(REQUIRED),r.get(RECOMMENDED),r.get(DEFAULT_BUDGET),r.get(CANDIDATE_NAME),r.get(CANDIDATE_URL),r.get(ALTERNATIVE_NAME),r.get(ALTERNATIVE_URL),r.get(NOTE),toInstant(r.get(CREATED_AT)));} }
